#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int partitionDisjoint(vector<int>& A) {
        int n = A.size();
        vector<int> leftMax(n), rightMin(n);
        leftMax[0] = A[0];
        rightMin[n-1] = A[n-1];

        for (int i = 1; i < n; ++i) {
            leftMax[i] = max(leftMax[i-1], A[i]);
        }
        for (int i = n - 2; i >= 0; --i) {
            rightMin[i] = min(rightMin[i+1], A[i]);
        }

        for (int i = 0; i < n - 1; ++i) {
            if (leftMax[i] <= rightMin[i+1]) return i + 1;
        }

        return n;
    }
};
